package sources

import (
	"encoding/json"
	"strings"
	"testing"

	"github.com/veritas501/mem-grep/internal/ir"
)

// These tests cover mem-grep's own filtering rules on single Codex items. They are not a format
// fixture: a real rollout fixture must be generated by Codex itself (see TODO(fixture) in codex.go).

func renderItems(t *testing.T, items ...string) []ir.Line {
	t.Helper()
	var lines []ir.Line
	push := func(role ir.Role, text string, turnStart bool, success *bool) {
		lines = append(lines, ir.Line{Role: role, Text: text, TurnStart: turnStart, Success: success})
	}
	names := map[string]string{}
	for _, it := range items {
		var p map[string]any
		if err := json.Unmarshal([]byte(it), &p); err != nil {
			t.Fatal(err)
		}
		renderCodexItem(p, push, names)
	}
	return lines
}

func TestCodexUserMessageFiltering(t *testing.T) {
	lines := renderItems(t,
		`{"type":"message","role":"developer","content":[{"type":"input_text","text":"sandbox rules"}]}`,
		`{"type":"message","role":"user","content":[{"type":"input_text","text":"<environment_context>\n<cwd>/x</cwd>\n</environment_context>"}]}`,
		`{"type":"message","role":"user","content":[{"type":"input_text","text":"# AGENTS.md instructions for /x\n\n<INSTRUCTIONS>\nbody\n</INSTRUCTIONS>"},{"type":"input_text","text":"用 pnpm 跑测试"}]}`,
	)
	if len(lines) != 1 || lines[0].Text != "USER: 用 pnpm 跑测试" || !lines[0].TurnStart {
		t.Fatalf("got %+v", lines)
	}
}

func TestCodexToolCallsAndExitCodes(t *testing.T) {
	lines := renderItems(t,
		`{"type":"function_call","name":"shell","call_id":"c1","arguments":"{\"command\":[\"pnpm\",\"test\"]}"}`,
		`{"type":"function_call_output","call_id":"c1","output":"FAIL\nProcess exited with code 1"}`,
		`{"type":"function_call_output","call_id":"c1","output":"ok\nProcess exited with code 0"}`,
	)
	if len(lines) != 3 || !strings.HasPrefix(lines[0].Text, "  → shell(command=") {
		t.Fatalf("got %+v", lines)
	}
	if !strings.HasPrefix(lines[1].Text, "  ✗ shell failed") || *lines[1].Success {
		t.Fatalf("non-zero exit: %+v", lines[1])
	}
	if !strings.HasPrefix(lines[2].Text, "  ✓ shell") || !*lines[2].Success {
		t.Fatalf("zero exit: %+v", lines[2])
	}
}

func TestCodexInteractiveSources(t *testing.T) {
	for src, want := range map[string]bool{`"cli"`: true, `"vscode"`: true, `null`: true, `"exec"`: false, `"mcp"`: false,
		`{"custom":"atlas"}`: true, `{"custom":"other"}`: false, `{"subagent":{"thread_spawn":{}}}`: false} {
		var v any
		json.Unmarshal([]byte(src), &v)
		if interactive(v) != want {
			t.Errorf("interactive(%s) = %v", src, !want)
		}
	}
}
